//! bikey as a Windows Text Services Framework (TSF) text service.
//!
//! Windows loads this DLL into every process that accepts text input,
//! including elevated ones, so it:
//! - must be installed somewhere only administrators can write (Program Files);
//! - never lets a panic cross a COM boundary (that would kill the host app);
//! - performs no file or network I/O and logs nothing.

#![cfg(windows)]
// Both fire inside code generated by windows-core's `#[implement]` macro.
#![allow(clippy::inline_always, clippy::ref_as_ptr)]

/// Development tracing (`--features trace`); compiles to nothing otherwise.
macro_rules! trace {
    ($($arg:tt)*) => {
        #[cfg(feature = "trace")]
        eprintln!("[bikey] {}", format_args!($($arg)*));
    };
}

mod display;
mod register;
mod service;
mod tsf;

use core::ffi::c_void;
use std::sync::atomic::{AtomicIsize, AtomicUsize, Ordering};

use windows::Win32::Foundation::{
    CLASS_E_CLASSNOTAVAILABLE, CLASS_E_NOAGGREGATION, E_POINTER, HINSTANCE, S_FALSE, S_OK,
};
use windows::Win32::System::Com::{IClassFactory, IClassFactory_Impl};
use windows::Win32::System::SystemServices::DLL_PROCESS_ATTACH;
use windows_core::{BOOL, GUID, HRESULT, IUnknown, Interface, Ref, implement};

/// COM class of the text service.
pub const CLSID_BIKEY: GUID = GUID::from_u128(0x645a0a82_ccae_4c5e_becb_6b1946ede140);
/// TSF language profile (Vietnamese, bikey).
pub const PROFILE_BIKEY: GUID = GUID::from_u128(0xf72c29de_6190_4af5_b5fd_2b2a52f997f2);
/// Preserved key that toggles Vietnamese on/off.
pub const GUID_TOGGLE_KEY: GUID = GUID::from_u128(0xd4c14d36_7872_4000_87fe_9ffeafd25ca9);

static MODULE: AtomicIsize = AtomicIsize::new(0);
/// Live COM objects plus `LockServer` locks; the DLL may unload at zero.
static REFERENCES: AtomicUsize = AtomicUsize::new(0);

pub(crate) fn module() -> HINSTANCE {
    HINSTANCE(MODULE.load(Ordering::Relaxed) as *mut c_void)
}

/// Counts a live object for `DllCanUnloadNow`.
pub(crate) struct DllRef;

impl DllRef {
    pub(crate) fn new() -> Self {
        REFERENCES.fetch_add(1, Ordering::SeqCst);
        DllRef
    }
}

impl Drop for DllRef {
    fn drop(&mut self) {
        REFERENCES.fetch_sub(1, Ordering::SeqCst);
    }
}

/// Run `f`, turning a panic into `E_UNEXPECTED` instead of unwinding into the host.
pub(crate) fn guard<T>(f: impl FnOnce() -> windows_core::Result<T>) -> windows_core::Result<T> {
    std::panic::catch_unwind(std::panic::AssertUnwindSafe(f))
        .unwrap_or_else(|_| Err(windows::Win32::Foundation::E_UNEXPECTED.into()))
}

#[unsafe(no_mangle)]
extern "system" fn DllMain(instance: HINSTANCE, reason: u32, _reserved: *mut c_void) -> BOOL {
    if reason == DLL_PROCESS_ATTACH {
        MODULE.store(instance.0 as isize, Ordering::Relaxed);
    }
    true.into()
}

#[implement(IClassFactory)]
struct ClassFactory;

impl IClassFactory_Impl for ClassFactory_Impl {
    fn CreateInstance(
        &self,
        outer: Ref<IUnknown>,
        iid: *const GUID,
        object: *mut *mut c_void,
    ) -> windows_core::Result<()> {
        guard(|| {
            if object.is_null() || iid.is_null() {
                return Err(E_POINTER.into());
            }
            // SAFETY: checked non-null; COM callers pass a valid out pointer.
            unsafe { *object = core::ptr::null_mut() };
            if outer.is_some() {
                return Err(CLASS_E_NOAGGREGATION.into());
            }
            let service: IUnknown = service::TextService::create();
            // SAFETY: `iid` and `object` are valid per the COM contract checked above.
            unsafe { service.query(iid, object) }.ok()
        })
    }

    fn LockServer(&self, lock: BOOL) -> windows_core::Result<()> {
        if lock.as_bool() {
            REFERENCES.fetch_add(1, Ordering::SeqCst);
        } else {
            REFERENCES.fetch_sub(1, Ordering::SeqCst);
        }
        Ok(())
    }
}

/// # Safety
/// Called by COM with valid pointers (checked for null anyway).
#[unsafe(no_mangle)]
pub unsafe extern "system" fn DllGetClassObject(
    clsid: *const GUID,
    iid: *const GUID,
    object: *mut *mut c_void,
) -> HRESULT {
    if clsid.is_null() || iid.is_null() || object.is_null() {
        return E_POINTER;
    }
    // SAFETY: checked non-null above.
    unsafe { *object = core::ptr::null_mut() };
    // SAFETY: checked non-null above.
    if unsafe { *clsid } != CLSID_BIKEY {
        return CLASS_E_CLASSNOTAVAILABLE;
    }
    let factory: IClassFactory = ClassFactory.into();
    // SAFETY: valid `iid`/`object` per the checks above.
    unsafe { factory.query(iid, object) }
}

#[unsafe(no_mangle)]
pub extern "system" fn DllCanUnloadNow() -> HRESULT {
    if REFERENCES.load(Ordering::SeqCst) == 0 {
        S_OK
    } else {
        S_FALSE
    }
}

/// Registers the COM class and the TSF profile. Needs administrator rights.
#[unsafe(no_mangle)]
pub extern "system" fn DllRegisterServer() -> HRESULT {
    match guard(register::register) {
        Ok(()) => S_OK,
        Err(e) => {
            // Leave nothing half-registered.
            let _ = guard(register::unregister);
            e.code()
        }
    }
}

#[unsafe(no_mangle)]
pub extern "system" fn DllUnregisterServer() -> HRESULT {
    match guard(register::unregister) {
        Ok(()) => S_OK,
        Err(e) => e.code(),
    }
}
